static const size_t g_embedded_assets_count = 30;

const EmbeddedAsset* embedded_asset_find(const char* name) {
    if (!name) return NULL;
    for (size_t i = 0; i < g_embedded_assets_count; i++) {
        const char* n = g_embedded_assets[i].name;
        /* match exact relative path or basename */
        if (strcmp(n, name) == 0) return &g_embedded_assets[i];
        const char* bn = strrchr(n, '/');
        if (bn && strcmp(bn + 1, name) == 0) return &g_embedded_assets[i];
    }
    return NULL;
}

const EmbeddedAsset* embedded_asset_find_by_suffix(const char* suffix) {
    if (!suffix) return NULL;
    size_t sl = strlen(suffix);
    for (size_t i = 0; i < g_embedded_assets_count; i++) {
        const char* n = g_embedded_assets[i].name;
        size_t nl = strlen(n);
        if (nl >= sl && strcmp(n + nl - sl, suffix) == 0) return &g_embedded_assets[i];
    }
    return NULL;
}

const EmbeddedAsset* embedded_assets_list(size_t* count) {
    if (count) *count = g_embedded_assets_count;
    return g_embedded_assets;
}
